import zipfile,os,tempfile,shutil,subprocess,sys
base=r'C:\Users\Vignesh\OneDrive\Desktop\vigneshstepprogram\java-gdb-activities-10\13'
for fn in sorted(os.listdir(base)):
 p=os.path.join(base,fn)
 if fn.lower().endswith('.zip'):
  print('ARCHIVE',fn)
  with zipfile.ZipFile(p) as z:
   names=z.namelist()
   for n in names: print(' ',n)
   if 'Java' not in fn: continue
   td=os.path.join(base,'_archive_extract_temp')
   shutil.rmtree(td,ignore_errors=True); os.makedirs(td)
   z.extractall(td)
   roots=[]
   for root,ds,fs in os.walk(td):
    if os.path.basename(root).lower()=='src' and any(f.endswith('.java') for f in fs): roots.append(root)
   print('SRC_ROOTS',roots)
   for src in roots:
    label=src
    files=[]
    for r,ds,fs in os.walk(src): files += [os.path.join(r,f) for f in fs if f.endswith('.java')]
    out=os.path.join(td,'classes_'+str(len(files)))
    os.makedirs(out,exist_ok=True)
    print('COMPILE',label,'FILES',len(files))
    cp=subprocess.run(['javac','-d',out]+files,text=True,capture_output=True)
    print('JAVAC_EXIT',cp.returncode)
    if cp.stdout: print(cp.stdout)
    if cp.stderr: print(cp.stderr)
    if cp.returncode==0:
     rp=subprocess.run(['java','-cp',out,'com.gdb.tests.TestAccountRulesEngine'],text=True,capture_output=True)
     print('TEST_EXIT',rp.returncode)
     if rp.stdout: print(rp.stdout)
     if rp.stderr: print(rp.stderr)
   shutil.rmtree(td,ignore_errors=True)
